function recordTitle(r){return r.data.name||r.data.fullName||r.data.studentId||r.data.studentName||r.id;}
function scopeLabel(scope){return [scope.schoolId,scope.subjectId,scope.courseId,scope.divisionId].map((id,i)=>{const type=['school','subject','course','division'][i],r=live(type).find(x=>x.id===id);return r?.data.name||'Sin nombre';}).join(' · ');}
