function renderAdmin(){const list=currentRole==='admin'?records.filter(r=>!r.deletedAt):[];$('#refresh-trash').hidden=currentRole!=='admin';$('#trash-records').hidden=currentRole!=='admin';$('#admin-records').innerHTML=list.map(r=>`<article class="data-card"><p class="eyebrow">${esc(LABELS[r.type]||r.type)}</p><h3>${esc(recordTitle(r))}</h3><p>${esc(r.id)}</p><div class="card-actions"><button class="quiet-button" data-edit-record="${esc(r.recordId)}">Editar</button><button class="quiet-button danger-button" data-delete-record="${esc(r.recordId)}">Mover a papelera</button></div></article>`).join('')||'<p class="empty">No hay registros cargados.</p>';$('#trash-records').innerHTML=trashRecords.map(r=>`<article class="data-card"><p class="eyebrow">PAPELERA · ${esc(LABELS[r.type]||r.type)}</p><h3>${esc(recordTitle(r))}</h3><p>${esc(r.id)}</p><div class="card-actions"><button class="quiet-button" data-restore-record="${esc(r.recordId)}">Restaurar</button></div></article>`).join('')||'<p class="empty">Papelera vacía.</p>';}
async function loadTrash(){if(currentRole!=='admin'){trashRecords=[];renderAdmin();return;}let cursor='',version=null,all=[];do{const page=await api('listTrash',{limit:300,...(cursor?{cursor}:{}),...(version!==null?{version}:{})});version=page.version;all.push(...(page.records||[]));cursor=page.nextCursor||'';}while(cursor);trashRecords=all.map(x=>({recordId:x.recordId,type:x.type,id:x.id,data:x.data,expectedVersion:Number(x.version||0),status:x.status,updatedAt:x.updatedAt}));renderAdmin();}
async function changeRecordState(r,restore=false){if(currentRole!=='admin'){toast('Solo una cuenta administradora puede administrar o restaurar registros.','error');return;}if(!confirm(restore?`¿Preparar la restauración de “${recordTitle(r)}”?`:`¿Preparar mover “${recordTitle(r)}” a la papelera? No se borra físicamente.`))return;const prior=stagedRecords.get(r.recordId);if(restore&&prior?.operation==='trash'){stagedRecords.delete(r.recordId);try{await persistStage();}catch(e){stagedRecords.set(r.recordId,prior);throw e;}const base=latestRemoteRecords.find(x=>x.recordId===r.recordId);if(base&&!records.some(x=>x.recordId===r.recordId))records.push(base);trashRecords=trashRecords.filter(x=>x.recordId!==r.recordId);render();renderAdmin();toast('Cancelé la baja pendiente; Sheets no recibió cambios.');return;}if(!restore&&Number(r.expectedVersion||0)===0&&prior&&!prior.operation){stagedRecords.delete(r.recordId);try{await persistStage();}catch(e){stagedRecords.set(r.recordId,prior);throw e;}records=records.filter(x=>x.recordId!==r.recordId);render();renderAdmin();toast('Cancelé el alta pendiente; Sheets no recibió cambios.');return;}const op={...r,operation:restore?'restore':'trash',expectedVersion:Number(r.expectedVersion||0),syncState:'staged'};try{await stageRecord(op);const i=records.findIndex(x=>x.recordId===r.recordId);if(restore){if(i>=0)records[i]={...op,deletedAt:undefined};trashRecords=trashRecords.filter(x=>x.recordId!==r.recordId);}else{if(i>=0)records.splice(i,1);trashRecords=[{...op,deletedAt:new Date().toISOString()},...trashRecords.filter(x=>x.recordId!==r.recordId)];}render();renderAdmin();toast('Operación preparada. Tocá “Sincronizar con Sheets” para confirmarla.');}catch(e){toast('No se pudo preparar la operación: '+e.message,'error');}}

