async function authenticate(){const btn=$('#login-button');btn.disabled=true;toast('Verificando usuario…','loading');try{const user=$('#access-user').value.trim(),d=await api('auth',{user,pass:$('#access-pass').value,includeInitialList:false});if(!d.sessionToken||!['admin','docente'].includes(d.access?.role)||!d.profile?.name||!d.profile?.mail)throw Error('BACKEND_VERSION_OUTDATED');sessionToken=d.sessionToken;currentUsername=d.username||user;currentRole=d.access?.role||'docente';currentScopes=d.access?.scopes||[];currentProfile=d.profile||{};try{sessionStorage.setItem('gradesAccess',JSON.stringify({username:currentUsername,role:currentRole,scopes:currentScopes,profile:currentProfile}));}catch(_){}stageOwner=await stageOwnerKey(user);stagedRecords=new Map();sessionStorage.setItem('gradesSession',sessionToken);await loadRemote();await restoreStage();await loadRemote();$('#access-pass').value='';toast('Sesión iniciada. Se restauran los borradores locales, sin enviarlos automáticamente.');}catch(e){sessionToken='';sessionStorage.removeItem('gradesSession');sessionStorage.removeItem('gradesAccess');currentUsername='';currentRole='docente';currentScopes=[];currentProfile={};$('#login-panel').hidden=false;$('#app-content').hidden=true;toast(e.message==='INVALID_CREDENTIALS'?'Usuario o contraseña incorrectos.':e.message==='BACKEND_VERSION_OUTDATED'?'El Apps Script publicado no devuelve rol y perfil. Actualizá el backend antes de usar la app.':'No se pudo conectar con Sheets: '+e.message,'error');}finally{btn.disabled=false;}}
async function loadRemote(retry=0){try{let cursor='',version=null,remote=[],pageRole=null,pageScopes=null,pageUser=null,pageProfile=null;do{const p=await api('listRecords',{limit:300,...(cursor?{cursor}:{}),...(version!==null?{version}:{})});version=p.version;pageRole=p.role||pageRole;pageScopes=p.scopes||pageScopes;if(p.username)pageUser=p.username;if(p.profile)pageProfile=p.profile;if(p.records)remote.push(...p.records);cursor=p.nextCursor||'';}while(cursor);if(!pageUser)throw Error('SESSION_EXPIRED');if(currentUsername&&currentUsername.toLowerCase()!==pageUser.toLowerCase()){sessionToken='';sessionStorage.removeItem('gradesSession');sessionStorage.removeItem('gradesAccess');currentUsername='';currentRole='docente';currentScopes=[];currentProfile={};stagedRecords.clear();records=[];throw Error('SESSION_EXPIRED');}currentUsername=pageUser;currentRole=pageRole||currentRole;currentScopes=pageScopes||currentScopes;currentProfile=pageProfile||currentProfile;try{sessionStorage.setItem('gradesAccess',JSON.stringify({username:currentUsername,role:currentRole,scopes:currentScopes,profile:currentProfile}));}catch(_){}if(stageOwner&&stageOwner!==await stageOwnerKey(currentUsername)){stagedRecords.clear();stageOwner=await stageOwnerKey(currentUsername);await restoreStage();}latestRemoteRecords=remote.map(x=>({recordId:x.recordId,type:x.type,id:x.id,data:x.data,expectedVersion:Number(x.version||0),syncState:'synced',updatedAt:x.updatedAt||new Date().toISOString()}));records=latestRemoteRecords.map(x=>({...x}));for(const r of stagedRecords.values()){if(r.operation==='trash'){records=records.filter(x=>x.recordId!==r.recordId);trashRecords=[{...r,status:'DELETED',deletedAt:r.deletedAt||new Date().toISOString()},...trashRecords.filter(x=>x.recordId!==r.recordId)];continue;}if(r.operation==='restore'){trashRecords=trashRecords.filter(x=>x.recordId!==r.recordId);const ix=records.findIndex(x=>x.recordId===r.recordId);if(ix<0)records.push({...r,status:'ACTIVE',deletedAt:undefined});else records[ix]={...r,status:'ACTIVE',deletedAt:undefined};continue;}const ix=records.findIndex(x=>x.recordId===r.recordId);if(ix<0)records.push(r);else records[ix]=r;}for(const r of [...records,...stagedRecords.values()].filter(x=>x.syncConflict)){const remoteVersion=latestRemoteRecords.find(x=>x.recordId===r.recordId);if(remoteVersion&&JSON.stringify(remoteVersion.data)!==JSON.stringify(r.data)){r.syncConflict=true;}else if(remoteVersion)r.syncConflict=false;}$('#connection').textContent='Conectado · Sheets';$('#connection').className='connection online';$('#login-panel').hidden=true;$('#app-content').hidden=false;render();return true;}catch(e){if(e.message==='DATA_CHANGED'&&retry<2)return loadRemote(retry+1);if(e.message==='UNAUTHORIZED'||e.message==='SESSION_EXPIRED'){sessionToken='';sessionStorage.removeItem('gradesSession');sessionStorage.removeItem('gradesAccess');currentUsername='';currentRole='docente';currentScopes=[];currentProfile={};$('#login-panel').hidden=false;$('#app-content').hidden=true;records=[];}$('#connection').textContent='Sin conexión a Sheets';$('#connection').className='connection offline';$('#login-panel').hidden=false;$('#app-content').hidden=true;sessionToken='';sessionStorage.removeItem('gradesSession');records=[];toast('No pude cargar los datos desde Sheets: '+e.message,'error');throw e;}}
