$('#equal-weights').onclick=async()=>{try{const list=assessmentsFor(),next=equalWeights(list.map(x=>({id:x.id,weight:x.data.weight,weightLocked:false}))),changes=next.map(x=>{const old=getOne('assessment',x.id);return {...old,data:{...old.data,weight:x.weight,weightLocked:false}};});await saveRecords(changes);render();toast('Pesos preparados. Tocá “Sincronizar con Sheets”.');}catch(err){toast('No se pudieron preparar los pesos: '+err.message,'error');}};
function resetTeacherForm(){teacherScopes=[];$('#teacher-form').reset();$('#teacher-editing').value='';$('#teacher-username').disabled=false;$('#teacher-form-title').textContent='Nuevo docente';$('#teacher-password').required=true;$('#teacher-password-help').textContent='Mínimo 12 caracteres. Confirmala abajo.';$('#cancel-teacher-edit').hidden=true;renderScopeBuilder();}
function editTeacher(username){const user=teachers.find(x=>x.username===username);if(!user)return;teacherScopes=user.scopes.map(x=>({...x}));$('#teacher-editing').value=user.username;$('#teacher-username').value=user.username;$('#teacher-username').disabled=true;$('#teacher-name').value=user.name;$('#teacher-mail').value=user.mail;$('#teacher-password').value='';$('#teacher-password-confirm').value='';$('#teacher-password').required=false;$('#teacher-password-help').textContent='Dejá ambos campos vacíos para conservarla; si la cambiás, usá mínimo 12 caracteres.';$('#teacher-form-title').textContent='Editar docente y permisos';$('#cancel-teacher-edit').hidden=false;renderScopeBuilder();$('#teacher-form').scrollIntoView({behavior:'smooth',block:'start'});}
