$('#scope-school').onchange=()=>{['subject','course','division'].forEach(k=>$(`#scope-${k}`).value='');renderScopeBuilder();};$('#scope-subject').onchange=()=>{['course','division'].forEach(k=>$(`#scope-${k}`).value='');renderScopeBuilder();};$('#scope-course').onchange=()=>{$('#scope-division').value='';renderScopeBuilder();};
$('#add-scope').onclick=()=>{
 const scope={schoolId:$('#scope-school').value,subjectId:$('#scope-subject').value,courseId:$('#scope-course').value,divisionId:$('#scope-division').value};
 if(Object.values(scope).some(x=>!x)){toast('Elegí escuela, materia, curso y división.','error');return;}
 if(!['school','subject','course','division'].every((type,i)=>live(type).some(r=>r.id===Object.values(scope)[i]&&r.expectedVersion>0&&!stagedRecords.has(r.recordId)))||!records.some(r=>!r.deletedAt&&!stagedRecords.has(r.recordId)&&['membership','assessment','schedule','attendance','observation','topic'].includes(r.type)&&['schoolId','subjectId','courseId','divisionId'].every(k=>r.data[k]===scope[k]))){toast('El curso debe tener al menos un horario, matrícula o registro académico ya sincronizado en Sheets.','error');return;}
 if(teacherScopes.some(x=>['schoolId','subjectId','courseId','divisionId'].every(k=>x[k]===scope[k]))){toast('Ese alcance ya está agregado.','error');return;}
 if(teacherScopes.length>=20){toast('Cada docente admite hasta 20 alcances.','error');return;}
 teacherScopes.push(scope);renderScopeBuilder();
};
$('#teacher-form').addEventListener('submit',async e=>{e.preventDefault();if(currentRole!=='admin'){toast('Solo admin puede gestionar usuarios.','error');return;}const f=e.currentTarget;if(!f.reportValidity())return;const editing=$('#teacher-editing').value,password=$('#teacher-password').value,confirmPassword=$('#teacher-password-confirm').value;if(!teacherScopes.length){toast('Agregá al menos un curso y división.','error');return;}if(password!==confirmPassword){toast('Las contraseñas no coinciden.','error');return;}if(!editing&&password.length<12){toast('La contraseña inicial debe tener al menos 12 caracteres.','error');return;}if(editing&&Boolean(password)!==Boolean(confirmPassword)){toast('Para cambiarla, completá y confirmá la nueva contraseña.','error');return;}const payload={username:$('#teacher-username').value.trim(),name:$('#teacher-name').value.trim(),mail:$('#teacher-mail').value.trim(),scopes:teacherScopes,...(editing?{existingUsername:editing}:{}),...(password?{password}:{})};const btn=f.querySelector('[type=submit]');btn.disabled=true;try{const out=await api('saveTeacher',payload);resetTeacherForm();await loadTeachers();toast(editing?'Docente y permisos actualizados.':'Docente creado. Entregale la contraseña temporal por un canal seguro.');}catch(err){toast('No se pudo guardar el docente: '+err.message,'error');}finally{btn.disabled=false;}});
$('#filter-student').oninput=renderGradebook;['school','subject','course','division','cutoff','subgroup'].forEach(k=>$(`#filter-${k}`).onchange=render);$$('.tab').forEach(b=>b.onclick=()=>{$$('.tab').forEach(x=>x.classList.toggle('active',x===b));$$('.tab-view').forEach(x=>x.hidden=x.id!==`view-${b.dataset.tab}`);if(b.dataset.tab==='users'&&currentRole==='admin')loadTeachers().catch(e=>toast('No se pudieron cargar docentes: '+e.message,'error'));});
function validateRecord(r){if(!TYPES.includes(r.type)||!r.id||!r.recordId.endsWith(`::${r.id}`)||!r.data||typeof r.data!=='object')throw Error(`Registro inválido: ${r.recordId}`);try{Gradebook.validateRecord(r);}catch(e){throw Error(e.message==='INVALID_STUDENT'?'Completá nombre e ID válido de cada estudiante antes de guardar.':'Revisá el registro '+r.id+'.');}if(r.type==='student'&&(!r.data.studentId||!r.data.fullName))throw Error('Completá nombre e ID de cada estudiante antes de guardar.');if(r.type==='grade'){if(!r.data.studentId||!r.data.assessmentId||!Object.hasOwn(STATUSES,r.data.status))throw Error('Calificación incompleta.');if(r.data.status==='graded'){const a=getOne('assessment',r.data.assessmentId),s=a&&getOne('scale',a.data.scaleId);if(!s)throw Error('La escala de esta instancia no está disponible.');numericValue(r.data,s.data);}}if(r.type==='scale')scaleValid(r.data);}
$('#refresh').onclick=async()=>{await loadRemote();await restoreStage();await loadRemote();};$('#sync-button').onclick=()=>records.some(r=>r.syncConflict)||[...stagedRecords.values()].some(r=>r.syncConflict)?resolveSyncConflict():syncStagedChanges().catch(()=>{});$$('[data-conflict-close]').forEach(b=>b.onclick=()=>$('#sync-conflict-dialog').close());$('#keep-remote').onclick=async()=>{const id=$('#sync-conflict-dialog').dataset.recordId,staged=stagedRecords.get(id),remote=staged?.operation==='restore'?trashRecords.find(x=>x.recordId===id):latestRemoteRecords.find(x=>x.recordId===id),i=records.findIndex(x=>x.recordId===id),staged=stagedRecords.get(id);stagedRecords.delete(id);try{await persistStage();}catch(e){if(staged)stagedRecords.set(id,staged);toast(e.message,'error');return;}if(remote&&i>=0)records[i]={...remote};else if(i>=0)records.splice(i,1);$('#sync-conflict-dialog').close();render();toast(remote?'Conservé la versión de Sheets.':'Descarté el borrador; el registro ya no existe en Sheets.');};$('#use-staged').onclick=async()=>{const id=$('#sync-conflict-dialog').dataset.recordId,staged=stagedRecords.get(id),remote=staged?.operation==='restore'?trashRecords.find(x=>x.recordId===id):latestRemoteRecords.find(x=>x.recordId===id);if(staged){staged.expectedVersion=Number(remote?.expectedVersion||0);delete staged.syncConflict;try{await persistStage();}catch(e){toast(e.message,'error');return;}const i=records.findIndex(x=>x.recordId===id);if(i>=0)records[i]={...staged};else records.push(staged);}$('#sync-conflict-dialog').close();toast('Tu versión quedó preparada; tocá Sincronizar con Sheets para enviarla.');render();};
function importRowRecord(row,index){let data;try{data=JSON.parse(row.DatosJSON);}catch(_){throw Error(`Fila ${index}: DatosJSON debe ser JSON válido.`);}const type=String(row.Tipo||''),id=String(row.ID||''),recordId=`${type}::${id}`,existing=records.find(x=>x.recordId===recordId);if(!type||!id)throw Error(`Fila ${index}: completá Tipo e ID.`);const version=Number(row.Version||0);if(!Number.isInteger(version)||version<0)throw Error(`Fila ${index}: Version debe ser un entero ≥ 0.`);const item={recordId,type,id,data,expectedVersion:version,syncState:'synced',updatedAt:new Date().toISOString()};validateRecord(item);return{item,existing,index};}
function importWorkbook(file){return file.arrayBuffer().then(buffer=>{const book=XLSX.read(buffer,{type:'array'}),sheet=book.Sheets.Registros;if(!sheet)throw Error('El archivo necesita una pestaña Registros. La pestaña Libreta exportada es solo de lectura.');const rows=XLSX.utils.sheet_to_json(sheet,{defval:'',raw:true});const parsed=rows.map((row,i)=>importRowRecord(row,i+2));const seen=new Set();for(const x of parsed){if(seen.has(x.item.recordId))throw Error(`ID duplicado en archivo: ${x.item.recordId}`);seen.add(x.item.recordId);}const candidates=parsed.map(x=>({...x,status:!x.existing?'create':JSON.stringify(x.existing.data)===JSON.stringify(x.item.data)?'same':x.existing.expectedVersion!==x.item.expectedVersion?'conflict':'update'}));$('#import-summary').textContent=`${candidates.filter(x=>x.status==='create').length} altas · ${candidates.filter(x=>x.status==='update').length} actualizaciones · ${candidates.filter(x=>x.status==='conflict').length} conflictos · ${candidates.filter(x=>x.status==='same').length} sin cambios. Los cambios se escribirán en Sheets al confirmar.`;$('#import-rows').innerHTML=candidates.map((x,i)=>`<tr><td>${x.index}</td><td>${esc(LABELS[x.item.type])} · ${esc(x.item.id)}</td><td>${x.status==='create'?'Alta':x.status==='same'?'Sin cambios':x.status==='update'?'Cambios contra la versión de Sheets':'Versión distinta a Sheets; comparar'}${x.existing?`<details><summary>Comparar actual y archivo</summary><pre>Actual:\n${esc(JSON.stringify(x.existing.data,null,2))}\nArchivo:\n${esc(JSON.stringify(x.item.data,null,2))}</pre></details>`:''}</td><td><select data-import="${i}"><option value="file">Usar el archivo</option><option value="keep">Conservar actual</option><option value="skip">Cancelar fila</option></select><details><summary>Corregir registro antes de importar</summary><textarea data-import-json="${i}" rows="4">${esc(JSON.stringify(x.item.data,null,2))}</textarea></details></td></tr>`).join('')||'<tr><td colspan="4" class="empty">La planilla está vacía.</td></tr>';importCandidates=candidates;$('#import-dialog').showModal();}).catch(err=>toast(err.message||'No pude leer el Excel.','error'));}
$('#export-xlsx').onclick=()=>{if(!sessionToken){toast('Iniciá sesión para exportar datos de Sheets.','error');return;}const book=XLSX.utils.book_new(),rows=records.filter(r=>!r.deletedAt).map(r=>({Tipo:r.type,ID:r.id,Version:Number(r.expectedVersion||0),Estado:r.syncState,DatosJSON:JSON.stringify(r.data)}));XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(rows),'Registros');const students=roster(),assessments=assessmentsFor(),wide=students.map(student=>{const row={Estudiante:student.data.fullName,ID:student.data.studentId};for(const a of assessments){const g=gradeFor(student.id,a.id);row[a.data.name]=g?`${g.data.value??''} · ${STATUSES[g.data.status]}`:'';}return row;});XLSX.utils.book_append_sheet(book,XLSX.utils.json_to_sheet(wide),'Libreta');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['Instrucciones'],['Registros: esquema normalizado, una fila por entidad. Editá aquí para preparar importación.'],['Libreta: vista ancha generada para lectura; no se importa como esquema.'],['Los cambios se preparan en esta app y se envían a Sheets al usar Sincronizar.'],['La ausencia de filas no borra datos.']]),'Instrucciones');XLSX.writeFile(book,'registro-notas.xlsx');};
$('#import-xlsx').onclick=()=>$('#xlsx-file').click();$('#xlsx-file').onchange=e=>{const file=e.target.files?.[0];e.target.value='';if(file){if(!sessionToken){toast('Iniciá sesión para importar en Sheets.','error');return;}loadRemote().then(()=>importWorkbook(file)).catch(()=>{});}};$$('[data-import-close]').forEach(button=>button.onclick=()=>$('#import-dialog').close());$('#import-form').onsubmit=async e=>{e.preventDefault();const submit=e.submitter;if(submit)submit.disabled=true;const changes=[];for(let i=0;i<importCandidates.length;i++){const choice=$(`[data-import="${i}"]`).value,x=importCandidates[i];if(choice==='keep'||choice==='skip')continue;try{const data=JSON.parse($(`[data-import-json="${i}"]`).value),r={...x.item,data,expectedVersion:Number(x.existing?.expectedVersion||0),syncState:'synced',updatedAt:new Date().toISOString()};validateRecord(r);changes.push(r);}catch(err){toast(`Fila ${x.index}: ${err.message||'contenido inválido'}`,'error');return;}}if(!confirm(`¿Preparar ${changes.length} registro(s)? Se enviarán a Sheets solo al tocar “Sincronizar”.`))return;try{await saveRecords(changes);$('#import-dialog').close();render();toast(`${changes.length} registro(s) preparados. Tocá “Sincronizar con Sheets”.`);}catch(err){toast('No se pudieron preparar los registros: '+err.message,'error');}finally{if(submit)submit.disabled=false;}};
